  const words = name.trim().split(/\s+/).filter(Boolean);
  const letters =
    words.length >= 2
      ? words.slice(0, 3).map((w) => w[0] ?? "").join("")
      : (words[0] ?? "task").slice(0, 3);
  return letters.toUpperCase().replace(/[^A-Z0-9]/g, "").slice(0, 4) || "TASK";
}

/**
 * Derives a project key that collides with nothing in `taken`, by appending
 * `2`, `3`, … and trimming the base so the result never exceeds 4 characters
 * — the same shape `uniqueSlug` gives addresses.
 */
export function uniqueProjectKey(input: string, taken: Iterable<string>): string {
  const base = input || "TASK";
  const used = new Set(taken);
  if (!used.has(base)) return base;

  for (let suffix = 2; suffix < 1_000; suffix += 1) {
    const suffixStr = String(suffix);
    const candidate = `${base.slice(0, 4 - suffixStr.length)}${suffixStr}`;
    if (!used.has(candidate)) return candidate;
  }
  throw new InvalidSlugError(base, "exhausted unique key suffixes");
}

